html:
{%- macro add_header(doc, letter_head, no_letterhead) -%}
    {% if letter_head and not no_letterhead %}
        <div class="letter-head">{{ letter_head }}</div>
    {% endif %}
{%- endmacro -%}

{% set source_label = "无" %}
{% set source_name = "" %}
{% set project_display = "" %}

{# --- 1. 确定关联来源 --- #}
{% if doc.work_order %}
    {% set source_label = "生产工单" %}
    {% set source_name = doc.work_order %}
{% elif doc.locations and doc.locations|length > 0 %}
    {% set first_line = doc.locations[0] %}
    {% if first_line.sales_order %}
        {% set source_label = "销售订单" %}
        {% set source_name = first_line.sales_order %}
    {% elif first_line.material_request %}
        {% set source_label = "物料请求" %}
        {% set source_name = first_line.material_request %}
    {% endif %}
{% endif %}

{# --- 2. 确定所属项目 --- #}
{% set found_project_id = "" %}

{% if doc.purpose == "Material Transfer for Manufacture" and doc.work_order %}
    {# 场景A: 制造发料 -> 查工单 #}
    {% set found_project_id = frappe.db.get_value("Work Order", doc.work_order, "project") %}

{% elif doc.purpose == "Material Transfer" and doc.locations and doc.locations|length > 0 and doc.locations[0].material_request %}
    {# 场景B: 材料转移 -> 查物料请求 #}
    {% set found_project_id = frappe.db.get_value("Material Request", doc.locations[0].material_request, "project") %}
{% endif %}

{# --- 3. 拼接项目名称: ID (名称) --- #}
{% if found_project_id %}
    {% set found_project_name = frappe.db.get_value("Project", found_project_id, "project_name") %}
    {% if found_project_name %}
        {% set project_display = found_project_id ~ " (" ~ found_project_name ~ ")" %}
    {% else %}
        {% set project_display = found_project_id %}
    {% endif %}
{% endif %}


<div class="page-break order-wrapper">
    <div id="header-html" class="hidden-pdf">
        {{ add_header(doc, letter_head, no_letterhead) }}
    </div>

    {%- if doc.docstatus==2-%}
        <div class="text-center watermark" document-status="cancelled">
            <h4>已作废</h4>
        </div>
    {%- endif -%}
    {%- if doc.docstatus==0 -%}
        <div class="text-center watermark" document-status="draft">
            <h4>草稿</h4>
        </div>
    {%- endif -%}

    <style>
        /* 针对 wkhtmltopdf 的图片修复 */
        .letter-head img {
            max-width: 100% !important;
            height: auto !important;
            width: auto !important; 
            display: inline-block !important;
        }
        .letter-head { margin-bottom: 15px; }

        /* 全局样式 */
        .order-wrapper {
            color: #000;
            font-size: 12px;
            line-height: 1.4; /* 稍微调小行高 */
        }

        .print-format-body { padding: 5px 0; }

        /* 表格样式 */
        table.info-table, table.items-table {
            border-collapse: collapse;
            width: 100%;
            margin-bottom: 20px;
            font-size: 12px;
        }

        table.info-table td, table.items-table td {
            border: 1px solid #000;
        }

        /* 基础信息表 Padding */
        table.info-table td {
            padding: 8px 10px;
            vertical-align: top;
        }

        /* 明细表 Padding (更紧凑) */
        table.items-table td {
            padding: 4px 5px; /* 上下4px, 左右5px */
            vertical-align: middle;
        }

        /* 隔行变色 */
        table.items-table tbody tr:nth-child(even) {
            background-color: #f2f2f2 !important;
            -webkit-print-color-adjust: exact;
        }

        thead.table-header { 
            background-color: #e0e0e0 !important;
            font-weight: bold; 
            -webkit-print-color-adjust: exact;
        }
        thead.table-header td { color: #000; padding: 6px 5px; }

        /* 勾选框样式 */
        .check-box-outline {
            width: 12px;
            height: 12px;
            border: 1px solid #000;
            display: inline-block;
            background-color: #fff;
            margin-top: 2px;
        }

        .text-center { text-align: center; }
        .text-left { text-align: left; }
        .text-right { text-align: right; }
        .text-bold { font-weight: bold; }

        /* 自定义 Label */
        .custom-label { 
            font-weight: bold; 
            margin-right: 5px; 
            display: inline-block;
            background: transparent !important;
            border: none !important;
            padding: 0 !important;
            color: #000 !important;
        }

        .secondary-text { font-size: 11px; color: #333; line-height: 1.2; }

        .watermark h4 {
            border: 2px solid #ccc; color: #ccc;
            padding: 10px 20px; 
            transform: rotate(-15deg);
            -webkit-transform: rotate(-15deg);
            position: absolute; top: 15%; left: 40%;
        }

        .signature-area { margin-top: 20px; width: 100%; font-size: 12px; }
        .signature-area td { border: none; padding: 10px; } 
        /* 签字线 */
        .signature-line { border-top: 1px solid #000; width: 90%; margin-top: 30px; }
    </style>

    <div class="print-format-body">

        <table class="info-table">
            <tr>
                <td style="width: 50%">
                    <span class="custom-label">单号:</span> 
                    <span class="text-bold">{{ doc.name }}</span>
                </td>
                <td style="width: 50%">
                    <span class="custom-label">日期:</span> 
                    {{ frappe.utils.format_date(doc.creation) }}
                </td>
            </tr>
            <tr>
                <td style="width: 50%">
                    <span class="custom-label">用途:</span> 
                    {{ _(doc.purpose) or "&nbsp;" }}
                </td>
                <td style="width: 50%">
                    <span class="custom-label">项目:</span> 
                    <span class="text-bold">{{ project_display or "&nbsp;" }}</span>
                </td>
            </tr>
            <tr>
                <td colspan="2">
                    <span class="custom-label">关联 ({{ source_label }}):</span> 
                    {{ source_name or "&nbsp;" }}
                </td>
            </tr>
        </table>

        <table class="items-table">
            <thead class="table-header">
                <tr>
                    <td class="text-center" style="width: 5%;">&nbsp;</td>
                    <td class="text-left" style="width: 37%;">物料信息</td>
                    <td class="text-left" style="width: 15%;">源仓库</td>
                    <td class="text-left" style="width: 20%;">批次/序列号</td>
                    <td class="text-right" style="width: 15%;">数量</td>
                    <td class="text-center" style="width: 8%;">✔</td>
                </tr>
            </thead>
            <tbody>
                {% for item in doc.locations %}
                <tr>
                    <td class="text-center">{{ loop.index }}</td>
                    <td>
                        <div class="text-bold">{{ item.item_code }}</div>
                        <div>{{ item.item_name }}</div>
                        {% if item.description and item.description != item.item_name %}
                            <div class="secondary-text" style="margin-top: 2px;">{{ item.description }}</div>
                        {% endif %}
                    </td>
                    <td>
                        {{ item.warehouse or "--" }}
                    </td>
                    <td>
                        {% if item.batch_no %}
                            <div class="secondary-text">[批] {{ item.batch_no }}</div>
                        {% endif %}
                        {% if item.serial_no %}
                            <div class="secondary-text">[序] {{ item.serial_no }}</div>
                        {% endif %}
                        {% if not item.batch_no and not item.serial_no %}
                            &nbsp;
                        {% endif %}
                    </td>
                    <td class="text-right">
                        <span class="text-bold" style="font-size: 13px;">{{ item.picked_qty }}</span>
                        <span>{{ item.uom }}</span>
                    </td>
                    <td class="text-center">
                        <div class="check-box-outline"></div>
                    </td>
                </tr>
                {% endfor %}
            </tbody>
        </table>

        <div style="margin-top: 5px; border: 1px solid #000; padding: 10px; min-height: 80px; font-size: 12px;">
            <div class="custom-label" style="margin-bottom: 4px;">备注:</div>
            <p style="margin: 0;">{{ doc.remarks or "&nbsp;" }}</p>
        </div>

        <table class="signature-area">
            <tr>
                <td style="width: 25%; vertical-align: top;">
                    <div>制单人:</div>
                    <div style="margin-top: 5px; font-weight: bold;">{{ doc.owner }}</div>
                    <div class="signature-line" style="margin-top: 5px;"></div>
                </td>
                <td style="width: 25%; vertical-align: top;">
                    <div>拣货人:</div>
                    <div class="signature-line"></div>
                </td>
                <td style="width: 25%; vertical-align: top;">
                    <div>复核人:</div>
                    <div class="signature-line"></div>
                </td>
                <td style="width: 25%; vertical-align: top;">
                    <div>接收人:</div>
                    <div class="signature-line"></div>
                </td>
            </tr>
        </table>

    </div>
</div>

